:root{--ink:#162722;--forest:#1b2925;--forest2:#263c33;--gold:#d8b987;--cream:#f6f1e7;--white:#fffdf9;--muted:#69746d;color-scheme:light;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);line-height:1.6}
a{color:inherit}
a:focus-visible,button:focus-visible{outline:3px solid #cb9c4d;outline-offset:4px}
[hidden]{display:none!important}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
/* The skip link must become truly visible, not only programmatically focused. */
.sr-only:focus-visible{position:fixed;top:12px;left:12px;z-index:10000;width:auto;height:auto;max-width:calc(100vw - 24px);overflow:visible;clip:auto;clip-path:none;white-space:normal;padding:12px 18px;border:2px solid #a47b3e;border-radius:5px;background:#fffdf7;color:#183a2a;box-shadow:0 10px 25px #0003;text-decoration:none;font:700 16px/1.4 system-ui,sans-serif}

.wrap{width:min(1220px,calc(100% - 52px));margin-inline:auto}
.header{background:var(--forest);color:white;border-bottom:1px solid rgba(255,255,255,.12);position:relative;z-index:3}
.header-inner{height:85px;display:flex;align-items:center;justify-content:space-between;gap:25px}
.brand{text-decoration:none;font:400 28px Georgia,"Times New Roman",serif;letter-spacing:.035em;color:#f9f1e5}
.brand .star{color:var(--gold);font-size:20px;padding-right:7px}
.navigation{display:flex;align-items:center;gap:27px}
.navigation a{font-size:12px;text-transform:uppercase;text-decoration:none;letter-spacing:.12em;color:#e7e7df}
.navigation a:hover{color:var(--gold)}
.tag{border:1px solid rgba(216,185,135,.6);padding:7px 13px;border-radius:100px;color:#dbc49e;font-size:10px;text-transform:uppercase;letter-spacing:.1em;white-space:nowrap}
.hero{background:var(--forest);color:#faf5ed;overflow:hidden;position:relative}
.hero:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 76% 52%,rgba(167,138,82,.11),transparent 45%);pointer-events:none}
.hero-grid{display:grid;grid-template-columns:1.03fr .97fr;align-items:center;min-height:635px;position:relative}
.hero-copy{padding:100px 0 105px;z-index:1}
.overline{font-weight:650;font-size:11px;text-transform:uppercase;letter-spacing:.29em;color:var(--gold);margin:0 0 24px}
.hero h1{font:400 clamp(55px,7vw,109px)/1.02 Georgia,"Times New Roman",serif;letter-spacing:-.045em;margin:0 0 26px;max-width:670px}
.hero-lead{font-size:17px;line-height:1.8;color:#d9dfd7;max-width:485px;margin:0 0 34px}
.button{display:inline-flex;align-items:center;justify-content:center;gap:25px;padding:15px 24px;min-height:52px;background:var(--gold);border:1px solid var(--gold);font-size:12px;font-weight:700;letter-spacing:.11em;text-transform:uppercase;text-decoration:none;color:var(--forest);transition:transform .2s,background .2s}
.button:hover{background:#f1d5a9;transform:translateY(-2px)}
.hero-note{font-size:12px;color:#9db4aa;margin-top:31px;letter-spacing:.03em}
.hero-art{height:580px;display:grid;place-items:center;position:relative;isolation:isolate}
.orbit{position:absolute;width:510px;height:510px;border:1px solid rgba(218,187,138,.23);border-radius:50%;box-shadow:0 0 0 46px rgba(197,157,101,.025),0 0 0 90px rgba(197,157,101,.025)}
.watch{position:relative;width:260px;height:350px;transform:rotate(-17deg);filter:drop-shadow(28px 31px 28px rgba(0,0,0,.65))}
.strap{position:absolute;left:71px;width:119px;height:160px;border-radius:24px;background:linear-gradient(90deg,#292622,#5a4838 50%,#2c2521);box-shadow:inset 8px 0 14px #1b1715,inset -8px 0 14px #241e1a}
.strap.top{top:-61px}.strap.bottom{bottom:-58px}
.case{position:absolute;left:16px;top:47px;width:229px;height:229px;border-radius:50%;padding:12px;background:linear-gradient(140deg,#f6daa8,#8a6137 38%,#ebc78e 69%,#65472d);box-shadow:0 0 0 3px #62482c,0 12px 30px #070c09}
.dial{position:relative;height:100%;border-radius:50%;background:radial-gradient(circle at 34% 28%,#47594b,#14261e 71%);box-shadow:inset 0 0 0 6px #0d1913,inset 0 0 0 8px #d2b784}
.mark{position:absolute;background:#f0d4a4;border-radius:2px}
.twelve,.six{height:23px;width:5px;left:calc(50% - 2.5px)}.twelve{top:20px}.six{bottom:20px}
.three,.nine{height:5px;width:23px;top:calc(50% - 2.5px)}.three{right:20px}.nine{left:20px}
.hour,.minute{position:absolute;left:calc(50% - 2px);border-radius:3px;background:#f8e7c8;transform-origin:50% 100%}
.hour{height:56px;width:5px;top:calc(50% - 56px);transform:rotate(310deg)}
.minute{height:78px;width:3px;top:calc(50% - 78px);transform:rotate(116deg)}
.center{position:absolute;left:calc(50% - 6px);top:calc(50% - 6px);width:12px;height:12px;background:#e0bd84;border-radius:50%}
.crown{position:absolute;right:-2px;top:142px;width:20px;height:37px;background:linear-gradient(90deg,#a7854c,#edd0a0,#826039);border-radius:5px;z-index:-1}
.art-label{position:absolute;bottom:27px;right:10px;font-size:10px;letter-spacing:.23em;color:#bdbaa9}
.intro{padding:97px 0;background:var(--cream)}
.intro-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:end}
.kicker{color:#9d7750}
h2{font:400 clamp(34px,4.3vw,60px)/1.14 Georgia,"Times New Roman",serif;letter-spacing:-.033em;margin:0}
.intro-text{margin:0;color:#5a655e;max-width:510px;font-size:17px;line-height:1.85}
.collection{background:var(--white);padding:110px 0 118px}
.section-title{max-width:750px;margin:0 0 35px}
.section-title p:last-child{color:var(--muted);font-size:16px}
.empty-state{background:#f6f1e9;border:1px solid #e1d9cb;padding:64px 25px;display:grid;justify-items:center;text-align:center}
.empty-state .symbol{font:normal 60px Georgia,serif;color:#bc9b6a}
.empty-state h3{font:400 32px Georgia,serif;margin:8px 0 12px}
.empty-state p{max-width:520px;color:#5d655e;margin:0 0 22px}
.status{padding:7px 12px;border:1px solid #c8b99f;border-radius:100px;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#5d675d}
.steps{background:#e7eae4;padding:105px 0}
.steps h2{margin-bottom:42px}
.steps-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.step{padding:30px 28px 35px;background:#f8f8f4;border:1px solid #cfd6cc;min-height:218px}
.step .number{font:400 33px Georgia,serif;color:#9d7d56}
.step h3{font:400 25px Georgia,serif;margin:20px 0 11px}
.step p{font-size:14px;line-height:1.7;color:#626c63;margin:0}
.outro{background:var(--forest2);color:#fff;padding:110px 0}
.outro-inner{display:grid;justify-items:center;text-align:center}
.outro h2{color:#fff;margin-bottom:24px}
.outro p{max-width:610px;color:#d1ddd6}
.footer{background:#121d18;color:#d6e1d9;padding:35px 0 50px}
.footer-inner{display:flex;justify-content:space-between;gap:26px;flex-wrap:wrap}
.footer p{font-size:12px;color:#aebfb5;margin:4px 0 0}
.footer a{color:#d7c29f}
@media(max-width:930px){.hero-grid{grid-template-columns:1fr}.hero-copy{padding:80px 0 15px}.hero-art{height:390px}.watch{transform:scale(.72) rotate(-17deg)}.orbit{width:380px;height:380px}.intro-grid{grid-template-columns:1fr;gap:25px}.steps-grid{grid-template-columns:1fr}.step{min-height:auto}}
@media(max-width:600px){.wrap{width:calc(100% - 38px)}.header-inner{height:auto;min-height:78px;align-items:flex-start;flex-wrap:wrap;padding:19px 0;gap:14px}.brand{font-size:24px}.navigation{width:100%;gap:23px;flex-wrap:wrap}.navigation a{font-size:10px}.tag{font-size:9px}.hero-copy{padding:66px 0 8px}.hero h1{font-size:clamp(49px,12.5vw,74px)}.hero-lead{font-size:15px}.hero-art{height:320px}.watch{transform:scale(.58) rotate(-17deg)}.orbit{width:300px;height:300px}.art-label{right:0;bottom:8px;font-size:9px}.intro,.collection,.steps,.outro{padding:70px 0}.empty-state{padding:45px 19px}.empty-state h3{font-size:27px}.steps h2{margin-bottom:26px}.footer-inner{flex-direction:column}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.button{transition:none}.button:hover{transform:none}}


/* Accessibility: kicker labels remain readable on ivory editorial backgrounds. */
.kicker{color:#70522f}

/* Atelier Montres — photo-first product gallery, built around existing verified models.
   All actions, affiliate disclosures, image zoom and comparisons remain usable. */
.am-view-toolbar{display:flex;gap:12px;align-items:center;justify-content:flex-end;flex-wrap:wrap;margin:3px 0 20px;padding:12px 0 4px;border-bottom:1px solid #e6ded2;color:#405649}
.am-view-toolbar-title{font:700 11px/1.4 system-ui,sans-serif;letter-spacing:.09em;text-transform:uppercase;margin-right:auto;color:#7b806e}
.am-view-options{display:inline-flex;gap:3px;padding:4px;border:1px solid #d7cabb;background:#eee8dd}
.am-view-options button{display:inline-flex;gap:7px;align-items:center;justify-content:center;cursor:pointer;background:transparent;border:1px solid transparent;min-height:44px;padding:9px 15px;color:#344f3d;font:650 12px/1.35 system-ui,sans-serif}
.am-view-options button[aria-pressed="true"]{background:#1c3b2a;color:#fff;border-color:#1c3b2a;box-shadow:0 3px 10px #1b332720}
.am-view-options button:focus-visible{outline:3px solid #bd9155;outline-offset:3px}
.am-view-options button:hover:not([aria-pressed="true"]){background:#e4dacb}
.am-view-symbol{font-size:18px;line-height:1;min-width:17px;text-align:center}
.am-view-explainer{width:100%;text-align:right;font:11px/1.5 system-ui,sans-serif;color:#667566;margin-top:-4px}
.am-gallery-facts{display:none}
/* View modes change layout only; card data and links always remain in the DOM. */
.aff-grid[data-view="gallery"]{grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;align-items:stretch}
.aff-grid[data-view="gallery"] .aff-card{min-width:0;border-color:#e7dfd2;background:#fffefa;box-shadow:0 10px 32px #20362b0b;transition:border-color .2s ease,box-shadow .2s ease}
.aff-grid[data-view="gallery"] .aff-card:hover{border-color:#b9a27d;box-shadow:0 16px 38px #20362b15}
.aff-grid[data-view="gallery"] .aff-illustration{height:auto;aspect-ratio:1/1;min-height:0;padding:12px!important;overflow:hidden}
.aff-grid[data-view="gallery"] .aff-product-photo{width:100%;height:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 8px 7px #26362618)}
.aff-grid[data-view="gallery"] .aff-art-label{display:none}
.aff-grid[data-view="gallery"] .aff-card-body{padding:15px 15px 18px;gap:0;min-width:0}
.aff-grid[data-view="gallery"] .aff-card-brand{margin:0 0 6px;font-size:9px;line-height:1.45}
.aff-grid[data-view="gallery"] .aff-card h3{min-height:0;margin:0 0 11px;font:400 clamp(16px,1.7vw,21px)/1.2 Georgia,serif;letter-spacing:-.015em;overflow-wrap:anywhere}
.aff-grid[data-view="gallery"] .aff-card-desc,.aff-grid[data-view="gallery"] .am-card-title,.aff-grid[data-view="gallery"] .aff-chips,.aff-grid[data-view="gallery"] .am-spec-line{display:none}
.aff-grid[data-view="gallery"] .am-gallery-facts{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:15px}
.aff-grid[data-view="gallery"] .am-gallery-facts span{display:inline-block;padding:6px 8px;background:#f2f1eb;color:#4b6553;border:1px solid #e2dfd5;font:650 10px/1.2 system-ui,sans-serif;overflow-wrap:anywhere}
.aff-grid[data-view="gallery"] .aff-card-actions{display:grid;grid-template-columns:minmax(0,1fr) 45px;align-items:stretch;gap:7px;margin-top:auto}
.aff-grid[data-view="gallery"] .aff-card-actions>a:first-child{font-size:11px;min-width:0;padding:9px 6px;min-height:44px}
.aff-grid[data-view="gallery"] .aff-card-actions button{min-width:44px;min-height:44px}
.aff-grid[data-view="gallery"] .aff-card-actions .am-affiliate-cta{grid-column:1/-1;margin-top:0;min-height:44px;padding:10px 6px;font-size:10px;white-space:normal}
.aff-grid[data-view="gallery"] .am-card-footer{gap:9px;align-items:flex-start;padding-top:10px}
.aff-grid[data-view="gallery"] .am-card-footer a,.aff-grid[data-view="gallery"] .am-card-footer label{font-size:11px;line-height:1.4}
.aff-grid[data-view="gallery"] .am-card-footer input{min-width:17px;min-height:17px;accent-color:#1c3b2a}
.aff-grid[data-view="gallery"] .am-card-footer .am-compare-check{display:inline-flex;align-items:center;gap:5px;min-height:38px;cursor:pointer}
.aff-grid[data-view="gallery"] .am-affiliate-note{font-size:10px;line-height:1.5;margin:8px 0;overflow-wrap:anywhere}
.aff-grid[data-view="gallery"] .aff-card-foot{display:none}
.aff-grid[data-view="gallery"] .am-card-seo-link{display:block;font-size:11px;line-height:1.5;margin:10px 0}
@media(max-width:980px){.aff-grid[data-view="gallery"]{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:760px){.aff-grid[data-view="gallery"]{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:620px){
 .am-view-toolbar{justify-content:space-between;gap:9px;margin-bottom:15px}
 .am-view-explainer{display:none}
 .am-view-toolbar-title{font-size:10px}
 .am-view-options button{font-size:11px;padding:9px 10px}
 .aff-grid[data-view="gallery"]{gap:10px}
 .aff-grid[data-view="gallery"] .aff-illustration{padding:7px!important;aspect-ratio:1/1.08}
 .aff-grid[data-view="gallery"] .aff-card-body{padding:12px 10px 14px}
 .aff-grid[data-view="gallery"] .aff-card h3{font-size:clamp(15px,4.2vw,19px);line-height:1.22;margin-bottom:8px}
 .aff-grid[data-view="gallery"] .am-gallery-facts{gap:4px;margin-bottom:10px}
 .aff-grid[data-view="gallery"] .am-gallery-facts span{font-size:9px;padding:5px 6px}
 .aff-grid[data-view="gallery"] .aff-card-actions{grid-template-columns:minmax(0,1fr) 44px;gap:5px}
 .aff-grid[data-view="gallery"] .aff-card-actions>a:first-child{font-size:10px;letter-spacing:0;line-height:1.3}
 .aff-grid[data-view="gallery"] .aff-card-actions .am-affiliate-cta{font-size:10px}
 .aff-grid[data-view="gallery"] .am-card-footer{display:flex;align-items:flex-start;flex-direction:column;gap:1px}
 .aff-grid[data-view="gallery"] .am-card-seo-link{font-size:10px;line-height:1.4}
}
@media(max-width:350px){.aff-grid[data-view="gallery"]{grid-template-columns:1fr}.aff-grid[data-view="gallery"] .aff-illustration{aspect-ratio:4/3}}
@media(prefers-reduced-motion:reduce){.aff-grid[data-view="gallery"] .aff-card{transition:none}}

/* Commercial integrity: the official Amazon Associates declaration remains
   fully visible above the catalogue; every commissionable exit is still
   individually identified in its button and its concise explanatory note. */
.aff-disclosure .am-affiliate-global-disclosure{margin-top:10px;font-weight:600;line-height:1.65}
.aff-grid[data-view="gallery"] .am-affiliate-note{margin-bottom:3px}

/* The floating help launcher must not cover an entire 180px watch card.
   Keep the full chat accessible by its existing aria-label and dialog. */
@media(max-width:620px){
 body[data-experience="affiliate"] .chat-launcher{
   width:54px;height:54px;min-width:54px;min-height:54px;
   right:12px;bottom:max(12px,env(safe-area-inset-bottom));
   padding:0;display:flex;align-items:center;justify-content:center;
   border-radius:50%;font-size:0;gap:0;box-shadow:0 7px 22px #071c1580
 }
 body[data-experience="affiliate"] .chat-launcher svg{width:24px;height:24px}
 body[data-experience="affiliate"]:has(#affCompareTray:not([hidden])) .chat-launcher{
   display:none
 }
}

/* Editorial discovery routes to existing factual collections. */
.am-discovery-paths{margin:17px 0 23px;padding:23px 24px;background:#182f26;color:#f6f0e4;border:1px solid #385244;box-shadow:0 15px 32px #11281b15}
.am-discovery-intro{margin-bottom:17px}
.am-discovery-eyebrow{display:block;margin-bottom:8px;font:700 10px/1.4 system-ui,sans-serif;letter-spacing:.17em;color:#d9bc86}
.am-discovery-intro strong{display:block;font:400 clamp(20px,2.6vw,29px)/1.2 Georgia,serif}
.am-discovery-intro p{margin:7px 0 0;color:#d2dfd3;font:12px/1.65 system-ui,sans-serif}
.am-discovery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.am-discovery-path{display:flex;flex-direction:column;gap:10px;min-width:0;min-height:169px;padding:17px 18px;color:#f9f6ed;background:#254338;border:1px solid #486454;text-decoration:none;transition:background .18s ease,border-color .18s ease,transform .18s ease}
.am-discovery-path-index{font:700 10px/1.4 system-ui,sans-serif;letter-spacing:.13em;color:#dbc38e}
.am-discovery-path strong{font:400 clamp(17px,2vw,23px)/1.25 Georgia,serif}
.am-discovery-path>span:nth-last-child(2){font:12px/1.55 system-ui,sans-serif;color:#d4dfd6}
.am-discovery-arrow{margin-top:auto;font:700 11px/1.4 system-ui,sans-serif;color:#f4d7a0}
.am-discovery-path:hover{background:#305243;border-color:#d0b478;transform:translateY(-2px)}
.am-discovery-path:focus-visible{outline:3px solid #f0d39c;outline-offset:3px}
@media(max-width:720px){.am-discovery-paths{margin:14px 0 20px;padding:19px 15px 17px}.am-discovery-grid{grid-template-columns:1fr;gap:8px}.am-discovery-path{min-height:0;gap:6px;padding:14px 15px}.am-discovery-path strong{font-size:19px}.am-discovery-path>span:nth-last-child(2){font-size:11px}.am-discovery-arrow{margin-top:3px}}
@media(prefers-reduced-motion:reduce){.am-discovery-path{transition:none}.am-discovery-path:hover{transform:none}}

/* 2026-10-31 photo art direction: an identical neutral watch stage for every
   brand and dial colour. Individual data-tone rules must not tint packshots.
   Background-only treatment: the authentic manufacturer pixels stay intact. */
body[data-experience="affiliate"] .aff-grid .aff-illustration[data-tone]:has(.aff-product-photo){
  background:radial-gradient(ellipse at 50% 35%,#fffefa 0%,#f3f3eb 50%,#e5eae1 100%)!important;
}
.aff-grid[data-view="gallery"] .aff-illustration:has(.aff-product-photo){
  display:grid;
  align-items:center;
  justify-items:center;
  position:relative;
  padding:clamp(9px,1.5vw,18px)!important;
}
.aff-grid[data-view="gallery"] .aff-illustration:has(.aff-product-photo)::before{
  display:block;
  position:absolute;
  inset:12px;
  width:auto;
  height:auto;
  border:1px solid #fffefa;
  border-radius:0;
  opacity:.85;
  pointer-events:none;
}
.aff-grid[data-view="gallery"] .aff-product-photo{
  display:block;
  object-fit:contain;
  object-position:center;
  max-width:100%;
  max-height:100%;
  filter:drop-shadow(0 11px 10px #1832251f);
  transition:transform .24s ease;
}
.aff-grid[data-view="gallery"] .aff-card:hover .aff-product-photo{transform:scale(1.025)}
.aff-grid[data-view="gallery"] .aff-card-brand{
  color:#806b46;
  font-weight:750;
  min-height:1.6em;
}
.aff-grid[data-view="gallery"] .aff-card h3{
  min-height:2.5em;
  margin-bottom:11px;
  color:#1e372a;
  letter-spacing:-.022em;
}
.aff-grid[data-view="gallery"] .am-gallery-facts{
  min-height:47px;
  align-content:start;
}
.aff-grid[data-view="gallery"] .am-gallery-facts span{
  background:#f4f3ee;
  border-color:#e1e2d7;
  color:#435c49;
}
.aff-grid[data-view="gallery"] .aff-card-actions{margin-top:auto}
.aff-grid[data-view="gallery"] .aff-card-actions>a:first-child{
  background:#1c392a;
  color:#fff;
  font-weight:700;
  text-decoration:none;
}
.aff-grid[data-view="gallery"] .aff-card-actions>a:first-child:hover{background:#31583e}
.aff-grid[data-view="gallery"] .am-card-footer .am-compare-check{min-height:44px}
.aff-grid[data-view="gallery"] .am-card-seo-link{
  display:flex;
  align-items:center;
  min-height:44px;
  margin:3px 0 0;
  text-decoration-thickness:1px;
  text-underline-offset:3px;
}
.aff-grid[data-view="gallery"] .am-card-seo-link:focus-visible{
  outline:3px solid #b78c51;
  outline-offset:2px;
}
@media(max-width:620px){
  .aff-grid[data-view="gallery"] .aff-illustration:has(.aff-product-photo){
    padding:9px!important;
  }
  .aff-grid[data-view="gallery"] .aff-illustration:has(.aff-product-photo)::before{inset:7px}
  .aff-grid[data-view="gallery"] .aff-card h3{min-height:2.45em}
  .aff-grid[data-view="gallery"] .am-gallery-facts{min-height:51px}
  .aff-grid[data-view="gallery"] .am-gallery-facts span{
    font-size:10px;
    padding:5px 6px;
    line-height:1.3;
  }
  .aff-grid[data-view="gallery"] .aff-card-body{padding:13px 11px 14px}
  .aff-grid[data-view="gallery"] .aff-card-actions>a:first-child{font-size:11px}
  .aff-grid[data-view="gallery"] .am-card-seo-link{font-size:11px}
}
@media(prefers-reduced-motion:reduce){
  .aff-grid[data-view="gallery"] .aff-product-photo{transition:none}
  .aff-grid[data-view="gallery"] .aff-card:hover .aff-product-photo{transform:none}
}

/* Browsing must not require scrolling through three tall marketing cards
   before reaching a single real watch. On phones, show an accessible,
   touch-scrollable discovery rail instead of a vertical three-card stack. */
