l-shops{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.detail-shops a{background:#fff;border:1px solid #cbcbbd;padding:11px 14px;text-decoration:none;font-size:12px;color:#294638}.detail-shops a:hover{background:#e9efe7}.detail-specs{border-top:1px solid #dcd8cb;margin-top:85px;padding-top:67px;display:grid;grid-template-columns:1fr 1fr;gap:60px}.detail-specs h2{margin-bottom:20px}.detail-specs p:not(.overline){max-width:520px;color:#68776a;line-height:1.8}.detail-specs dl{margin:0}.detail-specs dl>div{display:flex;justify-content:space-between;gap:20px;padding:17px 0;border-bottom:1px solid #dddace}.detail-specs dt{font-size:13px;color:#617063}.detail-specs dd{text-align:right;margin:0;font-size:13px;font-weight:650;color:#203b2b}.detail-error{background:#eee6d8;text-align:center;padding:80px 25px}.detail-error h1{font:400 48px Georgia,serif}.detail-error p{color:#556858;margin:0 0 25px}.detail-end{padding:100px 0;background:#263c30;color:#fff;text-align:center}.detail-end h2{color:#fff;max-width:680px;margin:0 auto 30px}
